(6200712, 915754, 114225, '<td valign="top">Great perspective, exposure, and composition. That''s pretty amazing how there are two levels of clouds to create this effect.</td>', 'Great perspective, exposure, and composition. That''s pretty amazing how there are two levels of clouds to create this effect.', '2010-10-25 11:01:36.000000', NULL, 1),
(6200713, 915960, 114225, '<td valign="top">This is pretty dang cool. The colors are the most striking part to me. I am sitting here wondering how this shot was done.</td>', 'This is pretty dang cool. The colors are the most striking part to me. I am sitting here wondering how this shot was done.', '2010-10-25 11:02:18.000000', NULL, 1),
(6200714, 915915, 114225, '<td valign="top">Great job setting up the mood to this photo, although I do wish it was ever so slightly brighter to see more of the details.</td>', 'Great job setting up the mood to this photo, although I do wish it was ever so slightly brighter to see more of the details.', '2010-10-25 11:04:41.000000', NULL, 1),
