(6201099, 915765, 3746, '<td valign="top">Nice understated image - has the surreality of a dream but with a firm footing in the real world. great work! 8</td>', 'Nice understated image - has the surreality of a dream but with a firm footing in the real world. great work! 8', '2010-10-25 18:38:07.000000', NULL, 1),
(6201100, 916093, 3746, '<td valign="top">Hmmm, not too sure on the processing on this one. Nice use of light &amp; shadow, but it all feels a bit too furry for my liking. real good shot though overall. 7</td>', 'Hmmm, not too sure on the processing on this one. Nice use of light & shadow, but it all feels a bit too furry for my liking. real good shot though overall. 7', '2010-10-25 18:38:51.000000', NULL, 1),
(6201101, 915867, 3746, '<td valign="top">My initial thought was "Seen it before" - but this has a great feel of a late autumnal day - I love driving when the weather is like this - the little hints of flare at the top are perfect,<br/> <br/>7</td>', 'My initial thought was "Seen it before" - but this has a great feel of a late autumnal day - I love driving when the weather is like this - the little hints of flare at the top are perfect, 7', '2010-10-25 18:40:33.000000', NULL, 1),
(6201102, 915700, 3746, '<td valign="top">Seems very shoehorned to me - compared to some of the entries this seems like the title was more of an afterthough to get it into the challenge. Not a bad photo, but not great by any means.</td>', 'Seems very shoehorned to me - compared to some of the entries this seems like the title was more of an afterthough to get it into the challenge. Not a bad photo, but not great by any means.', '2010-10-25 18:41:26.000000', NULL, 1),
(6201103, 915410, 3746, '<td valign="top">Brave shot on DPC, but I like it, it conveys the challenge well - the slightly surreal and pretentious title actually add to this. well done 7</td>', 'Brave shot on DPC, but I like it, it conveys the challenge well - the slightly surreal and pretentious title actually add to this. well done 7', '2010-10-25 18:42:05.000000', NULL, 1),
(6201104, 916067, 3746, '<td valign="top">TO me this seems like an badly processed image with attempts to cram it into the challenge. Its not a bad shot - but does nothing for me.</td>', 'TO me this seems like an badly processed image with attempts to cram it into the challenge. Its not a bad shot - but does nothing for me.', '2010-10-25 18:43:02.000000', NULL, 1),
