(6202063, 915911, 109227, '<td valign="top">Beautiful image.  This would make a great print. My favorite of the challenge.</td>', 'Beautiful image.  This would make a great print. My favorite of the challenge.', '2010-10-26 21:02:31.000000', NULL, 1),
(6202271, 916050, 65319, '<td valign="top">I find this image kind of funny...I find it kind of sad...but your dream definitely shows we live in a <a href="//www.youtube.com/watch?v=4N3N1MlvVc4" rel="nofollow" target="_blank">mad world</a>.  Hope this one does well for you.  (no vote...just lurking).</td>', 'I find this image kind of funny...I find it kind of sad...but your dream definitely shows we live in a mad world.  Hope this one does well for you.  (no vote...just lurking).', '2010-10-27 02:49:31.000000', NULL, 1),
(6202273, 916050, 49643, '<td valign="top">Coley is that from you? I like the way you have achieved the mood of the shot! Best wishes are with you with a ..10</td>', 'Coley is that from you? I like the way you have achieved the mood of the shot! Best wishes are with you with a ..10', '2010-10-27 02:50:28.000000', NULL, 1),
(6202274, 916124, 49643, '<td valign="top">Excellent emotions &amp; the concept! Like the way you have achieved the drama in this image!</td>', 'Excellent emotions & the concept! Like the way you have achieved the drama in this image!', '2010-10-27 02:51:11.000000', NULL, 1),
(6202275, 916149, 49643, '<td valign="top">Very interesting POV! I like the way you have framed &amp; added the drama in this image!</td>', 'Very interesting POV! I like the way you have framed & added the drama in this image!', '2010-10-27 02:52:25.000000', NULL, 1),
(6202348, 916093, 121359, '<td valign="top">Your presentation of this image links firmly with the ''dream'' theme.  Many people will connect with this shot from all different perspectives.  Fantastic.</td>', 'Your presentation of this image links firmly with the ''dream'' theme.  Many people will connect with this shot from all different perspectives.  Fantastic.', '2010-10-27 06:44:25.000000', NULL, 1),
(6202349, 915735, 121359, '<td valign="top">This image combines compostion and presentation to link strongly to the dream theme.  A powerful image for me.</td>', 'This image combines compostion and presentation to link strongly to the dream theme.  A powerful image for me.', '2010-10-27 06:46:35.000000', NULL, 1),
(6202351, 915599, 121359, '<td valign="top">This image was a bit disturbing for me.  You have presented a powerful and somewhat confronting vision for me.  Great contact with my feelings.</td>', 'This image was a bit disturbing for me.  You have presented a powerful and somewhat confronting vision for me.  Great contact with my feelings.', '2010-10-27 06:50:24.000000', NULL, 1),
(6202353, 916091, 121359, '<td valign="top">This image stood out to me.  The idea is great.  However, I would have liked to see part of the horse in sharper focus - I think that part would be the eye and perhaps the head. To me that would have emphasised the dream-like fuzziness of the rest of the image.</td>', 'This image stood out to me.  The idea is great.  However, I would have liked to see part of the horse in sharper focus - I think that part would be the eye and perhaps the head. To me that would have emphasised the dream-like fuzziness of the rest of the image.', '2010-10-27 06:54:30.000000', NULL, 1),
(6202359, 915811, 121359, '<td valign="top">Your image is subtle - very much so.  Would the connection to the competition theme be evident without the title/caption?  I like the thought and the image is beautiful.</td>', 'Your image is subtle - very much so.  Would the connection to the competition theme be evident without the title/caption?  I like the thought and the image is beautiful.', '2010-10-27 06:58:34.000000', NULL, 1),
(6202366, 916096, 121359, '<td valign="top">This is crazy good - you have packed so much into the image that cause the connected/unconnected feelings in my of dreaming. I love the presentation.</td>', 'This is crazy good - you have packed so much into the image that cause the connected/unconnected feelings in my of dreaming. I love the presentation.', '2010-10-27 07:01:37.000000', NULL, 1),
(6202368, 916140, 121359, '<td valign="top">This is classic dream symbolism - nicely taken and presented.  I like images with a strong connection to the competition theme.</td>', 'This is classic dream symbolism - nicely taken and presented.  I like images with a strong connection to the competition theme.', '2010-10-27 07:01:58.000000', NULL, 1),
(6202378, 915167, 57447, '<td valign="top">That happened to me when I quit smoking.  I like the shape &amp; blue tones.</td>', 'That happened to me when I quit smoking.  I like the shape & blue tones.', '2010-10-27 07:06:06.000000', NULL, 1),
(6202776, 915514, 83313, '<td valign="top">On top of the title, the blur makes the car look like a hearse. It works.</td>', 'On top of the title, the blur makes the car look like a hearse. It works.', '2010-10-27 14:16:50.000000', NULL, 1),
(6202778, 916021, 83313, '<td valign="top">Brings up a point. I''ve always been a bit concerned about Mitsubishi automobiles. Would you buy a car built by a company that used to make suicide aircraft?</td>', 'Brings up a point. I''ve always been a bit concerned about Mitsubishi automobiles. Would you buy a car built by a company that used to make suicide aircraft?', '2010-10-27 14:19:11.000000', NULL, 1),
(6202779, 915711, 83313, '<td valign="top">Looks like this turtle has turn signals mounted on his shell.</td>', 'Looks like this turtle has turn signals mounted on his shell.', '2010-10-27 14:20:18.000000', NULL, 1),
(6202788, 915167, 83313, '<td valign="top">Grog dreams of big fat whale. Can feed all Grog''s tribe for winter. Life is good for tribe until Grog dreams that whale is endangered and protected species. Uh oh. Grog now in trouble. Good thing is only dream. Grog now dream of things that don''t get Grog in trouble, like chasing of females. No, wait, that also get grog in trouble. Many times. Grog now have younglings and mother in laws.</td>', 'Grog dreams of big fat whale. Can feed all Grog''s tribe for winter. Life is good for tribe until Grog dreams that whale is endangered and protected species. Uh oh. Grog now in trouble. Good thing is only dream. Grog now dream of things that don''t get Grog in trouble, like chasing of females. No, wait, that also get grog in trouble. Many times. Grog now have younglings and mother in laws.', '2010-10-27 14:31:58.000000', NULL, 1),
(6202789, 915129, 83313, '<td valign="top">Looks vaguely like an alien skull of some sort.</td>', 'Looks vaguely like an alien skull of some sort.', '2010-10-27 14:37:34.000000', NULL, 1),
