(6205100, 915897, 120443, '<td valign="top">I like your Style.</td>', 'I like your Style.', '2010-10-30 15:15:43.000000', NULL, 1),
(6205144, 915754, 47470, '<td valign="top">I love the open door; it breaks up the symmetry perfectly.</td>', 'I love the open door; it breaks up the symmetry perfectly.', '2010-10-30 16:13:52.000000', NULL, 1),
(6205147, 916096, 47470, '<td valign="top">I really don''t like extreme HDR, but I must say that it does work well for this challenge.  Dreams usually are fairly hyper-realistic.  I half wish you had used a wide angle with some distortion on the light house.  Bear?</td>', 'I really don''t like extreme HDR, but I must say that it does work well for this challenge.  Dreams usually are fairly hyper-realistic.  I half wish you had used a wide angle with some distortion on the light house.  Bear?', '2010-10-30 16:17:22.000000', NULL, 1),
(6205148, 916108, 47470, '<td valign="top">As a stand-alone image, this is beautiful.  Such a great range of natural tones.  But for this challenge, I wish it had been a bit more "dreamy."  I don''t know how you could have done that without marring the beauty though.</td>', 'As a stand-alone image, this is beautiful.  Such a great range of natural tones.  But for this challenge, I wish it had been a bit more "dreamy."  I don''t know how you could have done that without marring the beauty though.', '2010-10-30 16:19:32.000000', NULL, 1),
(6205153, 915874, 47470, '<td valign="top">Everything is much too still for this to be a picture of a dream in which you were being chased!  I wanna see some blur!  Cue the wind and the running! : )</td>', 'Everything is much too still for this to be a picture of a dream in which you were being chased!  I wanna see some blur!  Cue the wind and the running! : )', '2010-10-30 16:21:18.000000', NULL, 1),
(6205156, 915897, 47470, '<td valign="top">She may be trapped by the edges of the image, but I wish there was a little more literal interpretation of the entrapment.  Great picture of the girl nonetheless.</td>', 'She may be trapped by the edges of the image, but I wish there was a little more literal interpretation of the entrapment.  Great picture of the girl nonetheless.', '2010-10-30 16:22:49.000000', NULL, 1),
(6205157, 916068, 47470, '<td valign="top">Wow, I don''t think you could have made this more dreamy if you tried.</td>', 'Wow, I don''t think you could have made this more dreamy if you tried.', '2010-10-30 16:24:32.000000', NULL, 1),
(6205159, 915239, 47470, '<td valign="top">I think the border is a bit too heavy on this.</td>', 'I think the border is a bit too heavy on this.', '2010-10-30 16:31:13.000000', NULL, 1),
(6205160, 916149, 47470, '<td valign="top">I love how the blade of grass looks like a knife in your pursuer''s hand.  My one nit-pick is that I wish there was just a bit more light of his face so we could make out the eyes a bit more.  I think the eyes might make this even scarier.</td>', 'I love how the blade of grass looks like a knife in your pursuer''s hand.  My one nit-pick is that I wish there was just a bit more light of his face so we could make out the eyes a bit more.  I think the eyes might make this even scarier.', '2010-10-30 16:34:00.000000', NULL, 1),
(6205161, 916098, 47470, '<td valign="top">I wish we saw a piece of a person coming out of the leaves!  Great colors.</td>', 'I wish we saw a piece of a person coming out of the leaves!  Great colors.', '2010-10-30 16:34:36.000000', NULL, 1),
(6205162, 915167, 47470, '<td valign="top">I''m not sure what it is that attracts me, but this is beautiful.</td>', 'I''m not sure what it is that attracts me, but this is beautiful.', '2010-10-30 16:35:59.000000', NULL, 1),
(6205163, 915898, 47470, '<td valign="top">Even though I''m really not a fan of exaggerated HDR, it really does work very well for this challenge.  The colors are perfect and the idea is great.</td>', 'Even though I''m really not a fan of exaggerated HDR, it really does work very well for this challenge.  The colors are perfect and the idea is great.', '2010-10-30 16:39:43.000000', NULL, 1),
