(6205607, 915911, 76335, '<td valign="top">Ribbon? It''s got to be... Fantastic.</td>', 'Ribbon? It''s got to be... Fantastic.', '2010-10-31 12:15:52.000000', NULL, 1),
(6205608, 915548, 76335, '<td valign="top">Those sickly greens and deep shadows really make this work.</td>', 'Those sickly greens and deep shadows really make this work.', '2010-10-31 12:15:55.000000', NULL, 1),
