(6205615, 915129, 76335, '<td valign="top">Daliesque. I like it.</td>', 'Daliesque. I like it.', '2010-10-31 12:16:24.000000', NULL, 1),
(6205616, 915239, 76335, '<td valign="top">I can''t score any image with crows less than a seven. Very challenge worthy all the same.</td>', 'I can''t score any image with crows less than a seven. Very challenge worthy all the same.', '2010-10-31 12:16:27.000000', NULL, 1),
(6205617, 916093, 76335, '<td valign="top">He''s dreaming of a new barber, no doubt. <br/> <br/>Okay, seriously, this is valid. Strong story. Good fantasy.</td>', 'He''s dreaming of a new barber, no doubt.  Okay, seriously, this is valid. Strong story. Good fantasy.', '2010-10-31 12:16:29.000000', NULL, 1),
(6205618, 916067, 76335, '<td valign="top">Coming back to this, I find it quite frightening. A seven for you.</td>', 'Coming back to this, I find it quite frightening. A seven for you.', '2010-10-31 12:16:31.000000', NULL, 1),
(6205619, 915915, 76335, '<td valign="top">All the magic of a childhood dream. What kid doesn''t dream of flying? A good fit for the challenge, and a welcome antidote to many of the darker entries (guilty!) in this challenge. A seven for you.</td>', 'All the magic of a childhood dream. What kid doesn''t dream of flying? A good fit for the challenge, and a welcome antidote to many of the darker entries (guilty!) in this challenge. A seven for you.', '2010-10-31 12:16:32.000000', NULL, 1),
(6205620, 916095, 76335, '<td valign="top">Beautiful. Feels like a dream about to begin. Or one that just ended.</td>', 'Beautiful. Feels like a dream about to begin. Or one that just ended.', '2010-10-31 12:16:41.000000', NULL, 1),
(6205621, 915167, 76335, '<td valign="top">Images like this nail the challenge as far as I''m concerned. Poetic title aside, the image stands alone as dream imagery. Ambiguous, personal, full of mystery, intrigue. Excellent work.</td>', 'Images like this nail the challenge as far as I''m concerned. Poetic title aside, the image stands alone as dream imagery. Ambiguous, personal, full of mystery, intrigue. Excellent work.', '2010-10-31 12:17:10.000000', NULL, 1),
(6205622, 916107, 76335, '<td valign="top">This has me laughing out loud (!). Don''t know why. Some poor unsuspecting lady motorist has been christened Aunt Minnie and posted to an online photography contest. Gotta love the Internet Age. <br/> <br/>Coming back to this several days later, the formidable Aunt Minnie is holding her own. Quite terrifying. Nine.</td>', 'This has me laughing out loud (!). Don''t know why. Some poor unsuspecting lady motorist has been christened Aunt Minnie and posted to an online photography contest. Gotta love the Internet Age.  Coming back to this several days later, the formidable Aunt Minnie is holding her own. Quite terrifying. Nine.', '2010-10-31 12:17:11.000000', NULL, 1),
(6205623, 916034, 76335, '<td valign="top">This is gripping and perfect for this challenge.</td>', 'This is gripping and perfect for this challenge.', '2010-10-31 12:17:15.000000', NULL, 1),
(6205626, 915548, 30364, '<td valign="top">Best of the literalist entries in the challenge.  Top five for me.  Thank you.</td>', 'Best of the literalist entries in the challenge.  Top five for me.  Thank you.', '2010-10-31 12:24:26.000000', NULL, 1),
(6205628, 915129, 30364, '<td valign="top">You must be a Zen Bardist then.  It''s convincing, wavering between states of comprehension as well as between states of being.  I haven''t had this dream myself yet, but when I do I expect it will look like this.  Top five for me.  Thank you.</td>', 'You must be a Zen Bardist then.  It''s convincing, wavering between states of comprehension as well as between states of being.  I haven''t had this dream myself yet, but when I do I expect it will look like this.  Top five for me.  Thank you.', '2010-10-31 12:27:12.000000', NULL, 1),
(6205629, 916129, 122895, '<td valign="top">Wonderful capture for this challenge.  Such peace!</td>', 'Wonderful capture for this challenge.  Such peace!', '2010-10-31 12:27:23.000000', NULL, 1),
(6205631, 916097, 122895, '<td valign="top">I love it!  This kind of scene would definitely have me dreaming.  A great capture of the light.</td>', 'I love it!  This kind of scene would definitely have me dreaming.  A great capture of the light.', '2010-10-31 12:28:35.000000', NULL, 1),
(6205632, 916062, 122895, '<td valign="top">Very appropriate photo and title for the challenge.  Love the color &amp; effect.</td>', 'Very appropriate photo and title for the challenge.  Love the color & effect.', '2010-10-31 12:28:56.000000', NULL, 1),
(6205633, 915599, 122895, '<td valign="top">I love the eye.  Nicely done.</td>', 'I love the eye.  Nicely done.', '2010-10-31 12:29:05.000000', NULL, 1),
(6205634, 915765, 122895, '<td valign="top">Great capture of light &amp; contrast.</td>', 'Great capture of light & contrast.', '2010-10-31 12:29:12.000000', NULL, 1),
(6205637, 916030, 122895, '<td valign="top">Wonderful capture for this challenge.</td>', 'Wonderful capture for this challenge.', '2010-10-31 12:30:06.000000', NULL, 1),
(6205638, 915735, 122895, '<td valign="top">Nice shot for your title which lend themselves to the challenge.</td>', 'Nice shot for your title which lend themselves to the challenge.', '2010-10-31 12:30:28.000000', NULL, 1),
(6205641, 916054, 122895, '<td valign="top">Great title.  Nice photo.  Good match for this challenge.</td>', 'Great title.  Nice photo.  Good match for this challenge.', '2010-10-31 12:31:35.000000', NULL, 1),
(6205642, 915897, 122895, '<td valign="top">Maybe a little more shadows, but a great shot for the title and challenge.</td>', 'Maybe a little more shadows, but a great shot for the title and challenge.', '2010-10-31 12:31:58.000000', NULL, 1),
(6205643, 915911, 122895, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2010-10-31 12:32:25.000000', NULL, 1),
(6205645, 916021, 122895, '<td valign="top">I like the editing for the photo to meet the challenge.</td>', 'I like the editing for the photo to meet the challenge.', '2010-10-31 12:33:17.000000', NULL, 1),
(6205650, 915767, 122895, '<td valign="top">I like the match of photo &amp; title.  Really captures the challenge for me.</td>', 'I like the match of photo & title.  Really captures the challenge for me.', '2010-10-31 12:33:57.000000', NULL, 1),
(6205651, 915742, 122895, '<td valign="top">I like it.  Reminds me of being outdoors here in Colorado, which always makes me dream.  For me, I would have lightened the edges more for a dreamy effect.</td>', 'I like it.  Reminds me of being outdoors here in Colorado, which always makes me dream.  For me, I would have lightened the edges more for a dreamy effect.', '2010-10-31 12:34:20.000000', NULL, 1),
(6205652, 915646, 122895, '<td valign="top">I''m not sure why you''d be dreaming this, but I like the light captured on the spider.</td>', 'I''m not sure why you''d be dreaming this, but I like the light captured on the spider.', '2010-10-31 12:34:54.000000', NULL, 1),
(6205657, 915685, 30364, '<td valign="top">It''s very beautiful.  A sense of transcendence is what I feel when I look at it. A movement from the left to the right.  The mist of tiny particles rising from the emergent side is perfect.  Top three for me.  Thank you.</td>', 'It''s very beautiful.  A sense of transcendence is what I feel when I look at it. A movement from the left to the right.  The mist of tiny particles rising from the emergent side is perfect.  Top three for me.  Thank you.', '2010-10-31 12:50:34.000000', NULL, 1),
(6205658, 915167, 30364, '<td valign="top">It''s a pretty chilling vision, tortured but beautiful.  And as I love Mumford &amp; Sons and I think this is a very apt expression of that track, I must give you a top two place in my voting.  Thank you.</td>', 'It''s a pretty chilling vision, tortured but beautiful.  And as I love Mumford & Sons and I think this is a very apt expression of that track, I must give you a top two place in my voting.  Thank you.', '2010-10-31 12:51:31.000000', NULL, 1),
(6205660, 916079, 30364, '<td valign="top">Beautifully done.  It''s remarkably convincing.  The anthropomorphic shapes are perfectly judged, the darker mass at lower centre creates the distinct feeling of some kind of crowding cabal or coven, and the single figure rendered in negative to the right suggests that Dream #9 is not going to be much fun either.  Thank you.  My top pick.</td>', 'Beautifully done.  It''s remarkably convincing.  The anthropomorphic shapes are perfectly judged, the darker mass at lower centre creates the distinct feeling of some kind of crowding cabal or coven, and the single figure rendered in negative to the right suggests that Dream #9 is not going to be much fun either.  Thank you.  My top pick.', '2010-10-31 12:57:22.000000', NULL, 1),
(6205711, 915767, 38930, '<td valign="top">He looks like a salmon swimming upstream</td>', 'He looks like a salmon swimming upstream', '2010-10-31 14:38:49.000000', NULL, 1),
(6205881, 915646, 50695, '<td valign="top">So cinematic, so 1940s cinematic! I''m putting this on the first floor of my dream gallery.</td>', 'So cinematic, so 1940s cinematic! I''m putting this on the first floor of my dream gallery.', '2010-10-31 18:41:56.000000', NULL, 1),
(6205884, 916132, 50695, '<td valign="top">I like how jagged this is. I''m putting this on the first floor of my dream gallery.</td>', 'I like how jagged this is. I''m putting this on the first floor of my dream gallery.', '2010-10-31 18:42:41.000000', NULL, 1);
